const AUTH_RETURN_URL='https://mason-trainer-adventure.vercel.app/';
const authReturnParams=new URLSearchParams(location.hash.slice(1));
const incomingAuthError=authReturnParams.get('error_code')||authReturnParams.get('error');
function emailRateLimited(error){return error?.code==='over_email_send_rate_limit'||/email.*rate.*(exceed|limit)|over_email_send_rate_limit/i.test(String(error?.message||error))}
function authErrorMessage(error){if(emailRateLimited(error))return 'Supabase has temporarily stopped sending sign-in emails. Repeated requests will not help. Use email and password below if your account has a password, or set one from a device already signed in. Otherwise wait for the email limit to reset.';return /expired|otp_expired|already.*used|Email link is invalid/i.test(String(error?.message||error))?'This sign-in link has expired or was already used. Request a fresh email when sending is available, and use only the newest link.':String(error?.message||error||'Unable to sign in.')}
const MAIL_WAIT_KEY='mason-email-wait-until';
function mailWaitRemaining(){return Math.max(0,Math.ceil((Number(localStorage.getItem(MAIL_WAIT_KEY))||0)-Date.now())/1000)}
function mailCooldown(seconds){localStorage.setItem(MAIL_WAIT_KEY,String(Date.now()+seconds*1000));showMailCooldown()}
function showMailCooldown(){const button=document.querySelector('#sendLogin button');if(!button)return;const left=mailWaitRemaining();button.disabled=left>0;button.textContent=left>60?'Email sending paused · try password':left>0?'Request another in '+Math.ceil(left)+'s':'Email a sign-in link';if(left>0)setTimeout(()=>{if(button.isConnected)showMailCooldown()},1000)}

const sb=window.supabase.createClient('https://dwuvciahzdnetqkmdqwx.supabase.co','sb_publishable_IiGqUkBqg8j44X9QUWefrg_bWKKWe-o',{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
let cloudUser=null,cloudBusy=false,cloudPending=false,cloudBase=null,cloudTimer,cloudMessage='Device only',authStarted=false;
const rawRender=render,rawSettings=settings,rawBind=bind,rawRedeem=redeem;
function checkResult(r){if(r.error)throw r.error;return r.data}
function cloudBanner(){let e=document.querySelector('#cloudbar');if(!e){e=document.createElement('div');e.id='cloudbar';document.querySelector('nav').after(e)}e.innerHTML=`<span>${cloudUser?'☁ '+esc(cloudMessage):'☁ Connect your family to share progress across devices'}</span><button id="cloudConnect">${cloudUser?'Family connection':'Set up family sync'}</button>`;e.querySelector('button').onclick=cloudPanel}
function backupCache(){if(cloudUser){localStorage.setItem('mason-family-'+cloudUser.id,JSON.stringify(state));localStorage.setItem('mason-pending-'+cloudUser.id,cloudPending?'1':'0')}else localStorage.setItem(KEY,JSON.stringify(state))}
save=function(){cloudPending=!!cloudUser;backupCache();cloudMessage='Saving…';cloudBanner();clearTimeout(cloudTimer);if(cloudUser)cloudTimer=setTimeout(()=>pushCloud().catch(syncError),350)};
function syncError(e){cloudMessage='Not synced · '+(e.message||'Connection unavailable');cloudBanner();toast('Progress stays on this device. Open Family connection to retry.');backupCache()}
function dataDetails(d){let {awards,...details}=d;return details}
async function pushCloud(){if(!cloudUser||cloudBusy)return;cloudBusy=true;try{while(cloudPending){cloudPending=false;const snap=JSON.parse(JSON.stringify(state)),u=cloudUser.id;checkResult(await sb.from('mason_trainer_families').upsert({user_id:u,settings:snap.settings},{onConflict:'user_id'}));
let details=Object.entries(snap.days).filter(([k,d])=>JSON.stringify(dataDetails(d))!==JSON.stringify(cloudBase?.days[k]?dataDetails(cloudBase.days[k]):null)).map(([k,d])=>({user_id:u,day:k,details:dataDetails(d)}));if(details.length)checkResult(await sb.from('mason_trainer_days').upsert(details,{onConflict:'user_id,day'}));
const awards=Object.entries(snap.days).flatMap(([k,d])=>d.awards.map(m=>({user_id:u,day:k,mission:m})));if(awards.length)checkResult(await sb.from('mason_trainer_awards').upsert(awards,{onConflict:'user_id,day,mission',ignoreDuplicates:true}));
for(const r of snap.spent)checkResult(await sb.from('mason_trainer_redemptions').upsert({user_id:u,id:r.id,cost:r.cost,label:r.label,day:r.date},{onConflict:'user_id,id',ignoreDuplicates:true}));
let claims=Object.keys(snap.claims).filter(k=>snap.claims[k]).map(k=>({user_id:u,week:k}));if(claims.length)checkResult(await sb.from('mason_trainer_claims').upsert(claims,{onConflict:'user_id,week',ignoreDuplicates:true}));cloudBase=snap;backupCache();}
cloudMessage='Saved to family cloud';cloudBanner();}catch(e){cloudPending=true;throw e}finally{cloudBusy=false;backupCache()}}
async function readCloudTable(t){let rows=[];for(let offset=0;;offset+=1000){let q=sb.from(t).select('*');if(t==='mason_trainer_awards')q=q.order('day').order('mission');else if(t==='mason_trainer_days')q=q.order('day');else if(t==='mason_trainer_redemptions')q=q.order('id');else if(t==='mason_trainer_claims')q=q.order('week');else q=q.order('user_id');let r=await q.range(offset,offset+999);checkResult(r);rows.push(...r.data);if(r.data.length<1000)return {data:rows,error:null}}}
async function pullCloud(){if(!cloudUser||cloudBusy||cloudPending)return;cloudBusy=true;try{const [f,ds,aw,rs,cs]=await Promise.all(['mason_trainer_families','mason_trainer_days','mason_trainer_awards','mason_trainer_redemptions','mason_trainer_claims'].map(readCloudTable));[f,ds,aw,rs,cs].forEach(checkResult);let next=empty();if(f.data[0])next.settings={...next.settings,...f.data[0].settings};for(const r of ds.data)next.days[r.day]={awards:[],checks:{},...r.details};for(const r of aw.data){if(!next.days[r.day])next.days[r.day]={awards:[],checks:{}};next.days[r.day].awards.push(r.mission)}next.spent=rs.data.map(r=>({id:r.id,cost:r.cost,label:r.label,date:r.day}));next.claims=Object.fromEntries(cs.data.map(r=>[r.week,true]));
// Preserve changes made while requests were in flight; retry upload instead of replacing them.
if(cloudPending)return;state=next;cloudBase=JSON.parse(JSON.stringify(next));backupCache();cloudMessage='Synced · '+new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'});if(!document.querySelector('#dialog').open)render();else cloudBanner();}finally{cloudBusy=false}}
function mergeProgress(remote,local){let r=JSON.parse(JSON.stringify(remote));for(const[k,d]of Object.entries(local.days)){let old=r.days[k];r.days[k]={...d,...old,awards:[...new Set([...(old?.awards||[]),...d.awards])]}}r.spent=[...new Map([...local.spent,...r.spent].map(x=>[x.id,x])).values()];r.claims={...local.claims,...r.claims};return r}
async function connectSession(session){if(!session?.user){cloudUser=null;cloudMessage='Device only';render();return}if(cloudUser?.id===session.user.id)return;cloudUser=session.user;let cached=localStorage.getItem('mason-family-'+cloudUser.id);let pending=localStorage.getItem('mason-pending-'+cloudUser.id)==='1';const old=JSON.parse(localStorage.getItem(KEY)||'null');state=cached?JSON.parse(cached):empty();cloudPending=pending;if(pending){await pushCloud()}await pullCloud();if(!cached&&old&&Object.values(old.days||{}).some(d=>d.awards?.length)){modal('<h2>Bring your points along?</h2><p>Your device has existing Trainer progress. Merge it into your family’s cloud record? Points for the same mission and date are counted only once.</p><button class="primary" id="mergeLocal">Merge existing progress</button><button id="skipLocal">Keep cloud progress only</button>');document.querySelector('#mergeLocal').onclick=async()=>{state=mergeProgress(state,old);save();document.querySelector('#dialog').close();render();await pushCloud().catch(syncError)};document.querySelector('#skipLocal').onclick=()=>document.querySelector('#dialog').close()}render()}
function cloudPanel(){modal(`<h2>${cloudUser?'Family connection':'Connect your family'}</h2>${cloudUser?`<p>Signed in as <b>${esc(cloudUser.email)}</b></p><p>Sign in with this same parent email on Mason’s device. His completed missions will appear in your Parent dashboard. Both devices share family access; Trainer mode is a simpler view, not a separate restricted child account.</p><div class="notice">${esc(cloudMessage)}</div><button class="primary" id="retryCloud">Sync now</button><button id="setAccountPassword" style="margin-top:12px">Set or change account password</button><button id="signoutCloud" style="margin-top:12px">Sign out on this device</button>`:`<p>Use the same parent email on both devices. Sign in once on Mason’s device, then let him use Daily missions.</p><form id="passwordLogin"><h3>Sign in without an email link</h3><label class="field">Parent email<input id="passwordEmail" type="email" autocomplete="username" required></label><label class="field">Account password<input id="accountPassword" type="password" autocomplete="current-password" required></label><button class="primary">Sign in with password</button><p class="muted">Use the same account as your other device. If you have not set a password, do that from Family connection on a device already signed in. This is your app account, not your Supabase dashboard password.</p></form><details><summary>Or sign in with an email link</summary><form id="sendLogin"><label class="field">Parent email<input type="email" id="familyEmail" autocomplete="email" required></label><button class="primary">Email a sign-in link</button></form><form id="verifyLogin"><label class="field">Sign-in code or copied email link<input id="emailToken" autocomplete="one-time-code" placeholder="Paste the link or code from the email" required></label><button class="primary">Connect this device</button></form><p class="muted">If the email contains a link, copy its full address and paste it above. Use an unused link from the newest email. Opening it first can use it up.</p></details><div id="authNotice" class="notice" role="status" hidden></div>`}`);
if(cloudUser){document.querySelector('#setAccountPassword').onclick=accountPasswordPanel;document.querySelector('#retryCloud').onclick=async()=>{try{await pushCloud();await pullCloud();document.querySelector('#dialog').close();render();toast('Family progress synced')}catch(e){syncError(e)}};document.querySelector('#signoutCloud').onclick=async()=>{if(cloudPending){await pushCloud().catch(syncError);if(cloudPending)return}await sb.auth.signOut({scope:'local'});cloudUser=null;cloudBase=null;state=JSON.parse(localStorage.getItem(KEY)||'null')||empty();document.querySelector('#dialog').close();render()};return}
document.querySelector('#passwordLogin').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;let note=document.querySelector('#authNotice');note.hidden=false;note.textContent='Signing in…';try{const result=await sb.auth.signInWithPassword({email:document.querySelector('#passwordEmail').value.trim(),password:document.querySelector('#accountPassword').value});checkResult(result);document.querySelector('#accountPassword').value='';document.querySelector('#dialog').close();await connectSession(result.data.session);toast('Family sync connected')}catch(error){note.textContent=authErrorMessage(error)}finally{button.disabled=false}};
showMailCooldown();
document.querySelector('#sendLogin').onsubmit=async e=>{e.preventDefault();if(mailWaitRemaining()>0)return;const button=e.target.querySelector('button');button.disabled=true;const email=document.querySelector('#familyEmail').value.trim();let note=document.querySelector('#authNotice');note.hidden=false;note.textContent='Sending…';try{checkResult(await sb.auth.signInWithOtp({email,options:{shouldCreateUser:true,emailRedirectTo:AUTH_RETURN_URL}}));mailCooldown(60);note.textContent='Check your email. Open only the newest sign-in link once, on this device.'}catch(error){note.textContent=authErrorMessage(error);if(emailRateLimited(error))mailCooldown(3600);else mailCooldown(60)}finally{showMailCooldown()}};
document.querySelector('#verifyLogin').onsubmit=async e=>{e.preventDefault();let email=document.querySelector('#familyEmail').value.trim(),token=document.querySelector('#emailToken').value.trim(),args;try{if(token.startsWith('http')){let u=new URL(token);if(u.protocol!=='https:')throw Error('Use the original HTTPS sign-in link from the email.');if(u.hostname!=='dwuvciahzdnetqkmdqwx.supabase.co')throw Error('Use the sign-in link from this app’s Supabase email.');let hash=u.searchParams.get('token')||u.searchParams.get('token_hash');if(!hash)throw Error('Copy the original sign-in link from the email, before opening it.');args={token_hash:hash,type:'email'}}else args={email,token,type:'email'};let res=await sb.auth.verifyOtp(args);checkResult(res);document.querySelector('#dialog').close();await connectSession(res.data.session);toast('Family sync connected')}catch(e){let note=document.querySelector('#authNotice');note.hidden=false;note.textContent=authErrorMessage(e)}}}
function accountPasswordPanel(){if(!cloudUser)return;modal(`<h2>Account password</h2><p>Set a password yourself, then use it with <b>${esc(cloudUser.email)}</b> to connect the iPad without a sign-in email.</p><div class="notice">This sets or changes the password for this Supabase Auth account. Other apps using the same account in educational-materials will use this password too. It does not change your Supabase dashboard password.</div><form id="setPasswordForm"><label class="field">New account password<input id="newAccountPassword" type="password" autocomplete="new-password" minlength="12" required></label><label class="field">Confirm password<input id="confirmAccountPassword" type="password" autocomplete="new-password" minlength="12" required></label><label class="check"><input id="passwordConsent" type="checkbox" required><span>I want to set or change this account’s password.</span></label><button class="primary">Save account password</button></form><div id="passwordResult" class="notice" role="status" hidden></div>`);document.querySelector('#setPasswordForm').onsubmit=async e=>{e.preventDefault();const message=document.querySelector('#passwordResult'),button=e.target.querySelector('button');message.hidden=false;const a=document.querySelector('#newAccountPassword'),b=document.querySelector('#confirmAccountPassword');if(a.value!==b.value){message.textContent='The passwords do not match.';return}button.disabled=true;try{checkResult(await sb.auth.updateUser({password:a.value}));a.value='';b.value='';message.textContent='Password saved. On the iPad, open Set up family sync and choose Sign in with password using this same parent email.';e.target.hidden=true}catch(error){message.textContent=error.code==='reauthentication_needed'?'Supabase requires a recent sign-in before changing this password. Keep this device signed in and try again after the email limit resets.':error.message}finally{button.disabled=false}}}
